export function crudeChunks(file, size = 400, overlap = 60) {
  const text = fs.readFileSync(file, 'utf8')
  const out = []
  for (let start = 0; start < text.length; start += size - overlap)
    out.push({ file, start, end: Math.min(start + size, text.length), text: text.slice(start, start + size) })
  return out
}
