const PROVIDER = process.env.EMBED ?? 'local'
export const EMBED_MODEL = PROVIDER === 'openai' ? 'text-embedding-3-small' : 'Xenova/all-MiniLM-L6-v2'
const CACHE_FILE = `data/embed-cache.${PROVIDER}.json`

const hash = (s) => createHash('sha1').update(s).digest('hex')
const cache = fs.existsSync(CACHE_FILE) ? JSON.parse(fs.readFileSync(CACHE_FILE, 'utf8')) : {}

let local
async function embedBatch(batch) {
  if (PROVIDER === 'openai') {
    const res = await fetch('https://api.openai.com/v1/embeddings', {
      method: 'POST',
      headers: { 'content-type': 'application/json', authorization: `Bearer ${process.env.OPENAI_API_KEY}` },
      body: JSON.stringify({ model: EMBED_MODEL, input: batch }),
    })
    if (!res.ok) { const e = new Error(`openai ${res.status}`); e.status = res.status; throw e }
    return (await res.json()).data.map((d) => d.embedding) // same ORDER as the batch
  }
  if (!local) {
    const { pipeline } = await import('@huggingface/transformers')
    local = await pipeline('feature-extraction', EMBED_MODEL, { dtype: 'fp32' })
  }
  return (await local(batch, { pooling: 'mean', normalize: true })).tolist()
}

export async function withRetry(fn, tries = 5) {
  for (let i = 0; i < tries; i++) {
    try { return await fn() } catch (e) {
      const retryable = e.status === 429 || e.status >= 500
      if (!retryable || i === tries - 1) throw e // a 401 will not fix itself
      const wait = 2 ** i * 500
      console.log(`retry in ${wait}ms: ${e.message}`)
      await new Promise((r) => setTimeout(r, wait))
    }
  }
}

export async function embedAll(texts) {
  const missing = [...new Set(texts.filter((t) => !cache[hash(t)]))]
  for (let i = 0; i < missing.length; i += 128) {
    const batch = missing.slice(i, i + 128)
    const vectors = await withRetry(() => embedBatch(batch))
    batch.forEach((t, j) => { cache[hash(t)] = vectors[j] }) // match by POSITION, never reorder
  }
  if (missing.length) {
    fs.mkdirSync('data', { recursive: true })
    fs.writeFileSync(CACHE_FILE, JSON.stringify(cache))
  }
  return { vectors: texts.map((t) => cache[hash(t)]), fresh: missing.length }
}

if (isMain(import.meta.url)) {
  const { vectors, fresh } = await embedAll(['how does a parent get linked to a student?', 'export function linkParentToStudent'])
  console.log(`model ${EMBED_MODEL}`)
  console.log(`${vectors.length} vectors, ${vectors[0].length} numbers each, ${fresh} new, ${vectors.length - fresh} from cache`)
}

export function cosine(a, b) {
  let dot = 0, sa = 0, sb = 0
  for (let i = 0; i < a.length; i++) { dot += a[i] * b[i]; sa += a[i] * a[i]; sb += b[i] * b[i] }
  return dot / (Math.sqrt(sa) * Math.sqrt(sb))
}

