// 1 if the expected file(s) are in the top k. Multi-file questions need ALL of them.
export function recallAtK(results, expected, k) {
  const files = new Set(results.slice(0, k).map((r) => norm(r.file)))
  return expected.map(norm).every((e) => files.has(e)) ? 1 : 0
}

