import { Project, SyntaxKind as K } from 'ts-morph'
import { listFiles, read } from '../load.mjs'
import { isMain } from '../main.mjs'

export const MIN = 80, MAX = 900 // mini-school. On a real repo: 200 / 1500

const project = new Project({ skipAddingFilesFromTsConfig: true, compilerOptions: { allowJs: true } })
const DECL = [K.FunctionDeclaration, K.ClassDeclaration, K.InterfaceDeclaration, K.TypeAliasDeclaration, K.EnumDeclaration]
const nameOf = (st) => st.getName?.() ?? st.getDeclarations?.()[0]?.getName() ?? '?'

function piece(sf, st) {
  const full = st.getFullText()
  const text = full.replace(/^\s*\n/, '')
  const startLine = sf.getLineAndColumnAtPos(st.getFullStart() + full.length - text.length).line
  return { text: text.trimEnd(), startLine, endLine: st.getEndLineNumber() }
}

// GIANTS: split a long function on its top-level statements, repeating the signature
function splitGiant(sf, st, c) {
  const body = st.getBody?.()
  if (!body || !body.getStatements) return [c]
  const sig = c.text.slice(0, c.text.indexOf('{') + 1)
  const parts = [[]]
  for (const s of body.getStatements()) {
    const cur = parts.at(-1)
    if (cur.length && cur.reduce((n, x) => n + x.text.length, 0) + s.getFullText().length > MAX - sig.length) parts.push([])
    parts.at(-1).push(piece(sf, s))
  }
  return parts.map((p, i) => ({ ...c, name: `${c.name} (part ${i + 1}/${parts.length})`, text: `${sig}\n  // part ${i + 1} of ${parts.length}\n${p.map((x) => x.text).join('\n')}`, startLine: p[0].startLine, endLine: p.at(-1).endLine }))
}

export function astChunk(source, file) {
  const sf = project.createSourceFile(`/virtual/${file}`, source, { overwrite: true })
  const header = [], decls = []
  for (const st of sf.getStatements()) {
    const isDecl = DECL.includes(st.getKind()) || (st.getKind() === K.VariableStatement && st.isExported())
    if (!isDecl) { header.push(piece(sf, st)); continue } // LEFTOVERS go to the header
    const c = { kind: st.getKindName(), name: nameOf(st), ...piece(sf, st) }
    decls.push(...(c.text.length > MAX ? splitGiant(sf, st, c) : [c]))
  }
  // CRUMBS: a tiny declaration joins the next one (Role + requireRole)
  const out = []
  let pending = null
  for (const c of decls) {
    const cur = pending ? { ...c, name: `${pending.name} + ${c.name}`, text: `${pending.text}\n\n${c.text}`, startLine: pending.startLine } : c
    pending = cur.text.length < MIN ? cur : null
    if (!pending) out.push(cur)
  }
  if (pending) out.length ? Object.assign(out.at(-1), { name: `${out.at(-1).name} + ${pending.name}`, text: `${out.at(-1).text}\n\n${pending.text}`, endLine: pending.endLine }) : out.push(pending)
  if (header.length) out.unshift({ kind: 'header', name: '(header)', text: header.map((h) => h.text).join('\n'), startLine: header[0].startLine, endLine: header.at(-1).endLine })
  return out.map((c) => ({ id: `${file}:${c.startLine}`, file, ...c }))
}

if (isMain(import.meta.url)) {
  let total = 0, fileChars = 0, chunkChars = 0
  for (const f of await listFiles()) {
    const src = read(f), cs = astChunk(src, f)
    total += cs.length; fileChars += src.length; chunkChars += cs.reduce((n, c) => n + c.text.length, 0)
    console.log(`${f}  ${cs.length} chunks`)
    for (const c of cs) console.log(`   ${c.name.padEnd(28)} lines ${c.startLine}-${c.endLine}  ${c.text.length} chars`)
  }
