// file -> files it imports, and the flipped version: file -> files that import it
export async function buildGraph() {
  const root = path.resolve(ROOT)
  const project = new Project({ skipAddingFilesFromTsConfig: true, compilerOptions: { allowJs: true } })
  for (const f of await listFiles()) project.addSourceFileAtPath(path.join(root, f))
