import { buildGraph } from '../graph.mjs'

const GUARD = 0.25 // only expand from a confident seed (MiniLM scores run lower than OpenAI's)
const SEEDS = 1    // expand from the top result only
const EXTRA = 2    // add at most 2 neighbours
let graph

// One hop: for the strong seed, pull in the best chunk of a file that IMPORTS it,
// right after the seed. Chunks that are already in the list are not added twice.
export async function expand(ranked) {
  graph ??= await buildGraph()
  const out = [], seen = new Set()
  let added = 0
  const push = (c) => { if (!seen.has(c.id)) { seen.add(c.id); out.push(c) } }
  for (const [i, c] of ranked.entries()) {
    push(c)
    if (i >= SEEDS || c.score < GUARD || added >= EXTRA) continue
    for (const f of graph.importedBy.get(c.file) ?? []) {
      const best = ranked.find((x) => x.file === f && !seen.has(x.id)) // ranked is sorted, so first = best
      if (best && added < EXTRA) { push({ ...best, via: c.file }); added++ }
    }
  }
  return out
}

