// "requireRole" -> ["requirerole", "require", "role"]: keep the WHOLE token so exact names still win
export function tokenizeCode(s) {
  return s
    .split(/[^A-Za-z0-9_]+/)
    .flatMap((t) => { const p = t.split(/(?<=[a-z])(?=[A-Z])/); return p.length > 1 ? [t, ...p] : [t] }) // camelCase
    .flatMap((t) => (t.includes('_') ? [t, ...t.split('_')] : [t]))                            // snake_case
    .map((t) => t.toLowerCase())
    .filter(Boolean)
}

const K1 = 1.2, B = 0.75
const built = {}

function build(name) {
  const docs = loadIndex(name).map((c) => ({ c, tf: new Map(), len: 0 }))
  const df = new Map()
  for (const d of docs) {
    const toks = tokenizeCode(d.c.text)
    d.len = toks.length
    for (const t of toks) d.tf.set(t, (d.tf.get(t) ?? 0) + 1)
    for (const t of d.tf.keys()) df.set(t, (df.get(t) ?? 0) + 1)
  }
  const avgLen = docs.reduce((n, d) => n + d.len, 0) / docs.length
  return { docs, df, avgLen, N: docs.length }
}

export function bm25Search(name, query, k = 20) {
  const { docs, df, avgLen, N } = (built[name] ??= build(name))
  const terms = [...new Set(tokenizeCode(query))]
  return docs
    .map(({ c, tf, len }) => {
      let score = 0
      for (const t of terms) {
        const f = tf.get(t); if (!f) continue
        const idf = Math.log(1 + (N - df.get(t) + 0.5) / (df.get(t) + 0.5))   // rare words matter more
        score += idf * (f * (K1 + 1)) / (f + K1 * (1 - B + (B * len) / avgLen)) // damped, length-normalised
      }
      return { ...c, score }
    })
    .filter((c) => c.score > 0)
    .sort((a, b) => b.score - a.score)
    .slice(0, k)
}

