// Reciprocal Rank Fusion: ignore the scores, use only positions.
export function rrf(lists, k = 60) {
  const score = new Map(), byId = new Map()
  for (const list of lists)
    list.forEach((c, rank) => {
      score.set(c.id, (score.get(c.id) ?? 0) + 1 / (k + rank + 1))
      byId.set(c.id, byId.get(c.id) ?? c)
    })
  return [...score].sort((a, b) => b[1] - a[1]).map(([id, s]) => ({ ...byId.get(id), score: s }))
}

