// A cross-encoder reads the question AND the chunk together and scores them.
// Local model: free, no key. Scores are logits: higher = more relevant (roughly -11 to +10).
export const RERANK_MODEL = 'Xenova/ms-marco-MiniLM-L-6-v2'
let tok, model

export async function rerank(question, candidates, keep = 20) {
  if (!candidates.length) return []
  if (!model) {
    const { AutoTokenizer, AutoModelForSequenceClassification } = await import('@huggingface/transformers')
    tok = await AutoTokenizer.from_pretrained(RERANK_MODEL)
    model = await AutoModelForSequenceClassification.from_pretrained(RERANK_MODEL, { dtype: 'fp32' })
  }
  const inputs = tok(candidates.map(() => question), { text_pair: candidates.map((c) => `${c.file}\n${c.text}`), padding: true, truncation: true })
  const scores = (await model(inputs)).logits.tolist().map((r) => r[0])
  return candidates
    .map((c, i) => ({ ...c, preRank: i + 1, rerank: scores[i] })) // keep the pre-rerank order as proof
    .sort((a, b) => b.rerank - a.rerank)
    .slice(0, keep)
}

