export const CHAT_MODEL = 'gpt-4o-mini'

export async function chat(messages, onToken = () => {}) {
  if (process.env.LLM === 'fake') {
    const text = 'linkParentToStudent pushes the student id onto parent.linkedStudentIds and saves the parent [1]. It is called from the POST /link admin route [2]. See also [9].'
    for (const word of text.split(/(?<= )/)) onToken(word) // "stream" it word by word
    return text
  }
  if (!process.env.OPENAI_API_KEY) throw new Error('no OPENAI_API_KEY (use --dry to see the prompt, or LLM=fake to test)')
  const res = await fetch('https://api.openai.com/v1/chat/completions', {
    method: 'POST',
    headers: { 'content-type': 'application/json', authorization: `Bearer ${process.env.OPENAI_API_KEY}` },
    body: JSON.stringify({ model: CHAT_MODEL, messages, stream: true, temperature: 0 }),
  })
  if (!res.ok) throw new Error(`openai ${res.status}: ${await res.text()}`)
  let full = '', buf = ''
  const decoder = new TextDecoder()
  for await (const bytes of res.body) {               // the answer arrives piece by piece
    buf += decoder.decode(bytes, { stream: true })
    const lines = buf.split('\n'); buf = lines.pop()
    for (const line of lines) {
      if (!line.startsWith('data: ') || line === 'data: [DONE]') continue
      const delta = JSON.parse(line.slice(6)).choices[0]?.delta?.content ?? ''
      onToken(delta); full += delta                    // print it AND keep the whole thing
    }
  }
  return full
}

