export const countTokens = (s) => enc.encode(s).length

// add chunks in ranked order until the budget is used; no single chunk may take more than 40%
export function selectByBudget(ranked, budget = 6000) {
  const selected = []
  let used = 0
  for (const c of ranked) {
    const t = countTokens(c.text)
    if (t > budget * 0.4) continue
    if (used + t > budget) break
    selected.push(c); used += t
  }
  return { selected, used }
}

