export const THRESHOLD = -5 // from your eval: unanswerable questions top out around -5 with this reranker

// The whole question -> answer path, reusable by the CLI and the web server.
export async function answer(question, { dry = false, onToken } = {}) {
  const { vectors: [qVec] } = await embedAll([question])
  const fused = hybrid(question, qVec).slice(0, 20)
  const ranked = await rerank(question, fused)
  const { selected, used } = selectByBudget(ranked.slice(0, 8), 6000)
  const base = { question, ranked, fused, selected, used }

  // layer 1: nothing relevant -> do not even call the model (free, instant)
  if (!ranked.length || ranked[0].rerank < THRESHOLD)
    return { ...base, answer: null, reason: `No relevant code found (top rerank score ${ranked[0]?.rerank.toFixed(1)}, threshold ${THRESHOLD})` }

  const messages = buildPrompt(question, selected)
  if (dry) return { ...base, messages, answer: null, reason: 'dry run' }

  // layer 2: the model itself says NOT_FOUND
  const raw = await chat(messages, onToken)
  if (raw.trim().startsWith('NOT_FOUND')) return { ...base, messages, answer: null, reason: 'model declined: the code does not contain the answer' }
  return { ...base, messages, answer: raw, reason: null }
}

