const name = process.argv[2] ?? 'naive'
const chunker = CHUNKERS[name]
if (!chunker) { console.log(`unknown chunker "${name}". Try: ${Object.keys(CHUNKERS).join(', ')}`); process.exit(1) }

const hash = (s) => createHash('sha1').update(s).digest('hex')
const files = await listFiles()
const prev = fs.existsSync(indexPath(name)) ? loadIndex(name) : []
const prevHash = new Map(prev.map((c) => [c.file, c.fileHash]))

const changed = files.filter((f) => hash(read(f)) !== prevHash.get(f))
const kept = prev.filter((c) => files.includes(c.file) && !changed.includes(c.file)) // also drops deleted files
const fresh = changed.flatMap((f) => chunker(read(f), f).map((c) => ({ ...c, fileHash: hash(read(f)) })))

if (name === 'ast+graph') {
  const { imports, importedBy } = await buildGraph()
  for (const c of fresh)
    c.embedText = `${c.file} - ${c.name}\nimports: ${(imports.get(c.file) ?? []).join(', ') || 'nothing'}\nimported by: ${(importedBy.get(c.file) ?? []).join(', ') || 'nothing'}\n\n${c.text}`
}

const { vectors, fresh: embedded } = await embedAll(fresh.map((c) => c.embedText ?? c.text))
fresh.forEach((c, i) => { c.vector = vectors[i] }) // attach them!
const chunks = [...kept, ...fresh]
saveIndex(name, chunks)
console.log(`${files.length} files, ${changed.length} changed -> ${chunks.length} chunks in data/index-${name}.json (${fresh.length} re-chunked, ${embedded} sent to the embedder)`)

