// Serial vs unlimited vs batched, and retry with backoff, against a fake API.
let calls = 0, failuresLeft = 2
async function fakeEmbed(batch) {
  calls++
  if (failuresLeft-- > 0) { const e = new Error('429 too many requests'); e.status = 429; throw e }
  return batch.map(() => [0.1, 0.2])
}
async function withRetry(fn, tries = 5) {
  for (let i = 0; i < tries; i++) {
    try { return await fn() } catch (e) {
      if (!(e.status === 429 || e.status >= 500) || i === tries - 1) throw e // 401: give up at once
      const wait = 2 ** i * 500
      console.log(`  retry in ${wait}ms: ${e.message}`)
      await new Promise((r) => setTimeout(r, wait))
    }
  }
}

const texts = Array.from({ length: 300 }, (_, i) => `chunk ${i}`)

calls = 0; failuresLeft = 0
for (const t of texts) await fakeEmbed([t])
console.log(`serial, one await per text : ${calls} requests`)

calls = 0
await Promise.all(texts.map((t) => fakeEmbed([t])))
console.log(`Promise.all, no limit      : ${calls} requests at the SAME moment (a real API rate-limits you)`)

calls = 0; failuresLeft = 2
for (let i = 0; i < texts.length; i += 128) await withRetry(() => fakeEmbed(texts.slice(i, i + 128)))
console.log(`batched by 128 with retry  : ${calls} requests (3 batches + 2 retries)`)

failuresLeft = 0
const bad = async () => { const e = new Error('401 invalid key'); e.status = 401; throw e }
await withRetry(bad).catch((e) => console.log(`a 401 is not retried       : ${e.message}`))

