// Cut on the structure the document already has: headings. Keep the heading trail.
export function headingChunk(md, file, MIN = 60) {
  const lines = md.split('\n'), trail = [], chunks = []
  let buf = [], start = 1
  const flush = (end) => {
    const text = buf.join('\n').trim(); buf = []
    if (text.length < MIN) return // too small to stand alone
    const headingTrail = trail.filter(Boolean).join(' > ')
    chunks.push({ id: `${file}:${start}`, file, name: headingTrail, text, startLine: start, endLine: end, headingTrail, embedText: `${headingTrail}\n\n${text}` })
  }
  lines.forEach((line, i) => {
    const h = line.match(/^(#{1,6})\s+(.*)/)
    if (h) { flush(i); trail.length = h[1].length - 1; trail[h[1].length - 1] = h[2]; start = i + 2 }
    else buf.push(line)
  })
  flush(lines.length)
  return chunks
}

