// Similarity ignores time. Hard filters and a soft recency decay fix that.
const TODAY = new Date('2026-10-01')
const tickets = [
  { id: 101, date: '2021-02-10', product: 'checkout', score: 0.82, text: 'Card payment fails on old checkout page' },
  { id: 202, date: '2026-08-20', product: 'checkout', score: 0.74, text: 'Payment fails when card needs OTP' },
  { id: 303, date: '2025-11-02', product: 'app', score: 0.71, text: 'App crashes after payment' },
  { id: 404, date: '2019-06-01', product: 'checkout', score: 0.40, text: 'Old refund rule (removed)' },
]
const age = (t) => (TODAY - new Date(t.date)) / 86400000
const decay = (t) => Math.pow(0.5, age(t) / 550)          // ~18 month half-life
const soft = (t) => t.score * (0.55 + 0.45 * decay(t))   // floor 0.55: old answers stay reachable

const show = (label, list, key) => console.log(`${label}\n${list.map((t) => `  #${t.id} ${t.date} ${key(t).toFixed(2)}  ${t.text}`).join('\n')}`)
show('similarity only:', [...tickets].sort((a, b) => b.score - a.score), (t) => t.score)
show('with recency decay:', [...tickets].sort((a, b) => soft(b) - soft(a)), soft)

const filter = (opts) => tickets.filter((t) => (!opts.product || t.product === opts.product) && (!opts.since || t.date >= opts.since))
const narrow = filter({ product: 'checkout', since: '2026-09-01' })
console.log(`filter checkout since 2026-09-01: ${narrow.length} results -> ${narrow.length ? 'ok' : 'fall back to unfiltered search instead of showing nothing'}`)

