import { rrf } from './search/rrf.mjs'
import { saveIndex } from './store.mjs'
import { recallAtK, mrr, avg } from './eval/metrics.mjs'

// loader + chunker: the only new parts
const chunks = fs.readdirSync('notes').sort().flatMap((f) => headingChunk(fs.readFileSync(`notes/${f}`, 'utf8'), `notes/${f}`))
const { vectors } = await embedAll(chunks.map((c) => c.embedText))
chunks.forEach((c, i) => { c.vector = vectors[i] })
saveIndex('notes', chunks)
console.log(`${chunks.length} note chunks indexed`)

// everything below is unchanged machinery
const qs = JSON.parse(fs.readFileSync('questions-notes.json', 'utf8'))
const { vectors: qv } = await embedAll(qs.map((q) => q.q))
const vec = (i) => chunks.map((c) => ({ ...c, score: cosine(c.vector, qv[i]) })).sort((a, b) => b.score - a.score)
const report = (label, run) => {
  const rows = qs.map((q, i) => { const r = run(q, i); return { r1: recallAtK(r, q.expect, 1), mrr: mrr(r, q.expect) } })
  console.log(`${label.padEnd(8)} r@1 ${avg(rows.map((r) => r.r1)).toFixed(2)}  mrr ${avg(rows.map((r) => r.mrr)).toFixed(2)}`)
}
report('vector', (q, i) => vec(i))
report('bm25', (q) => bm25Search('notes', q.q, 20))
report('hybrid', (q, i) => rrf([vec(i), bm25Search('notes', q.q, 20)]))
